<section class="page-heading"><div><p class="eyebrow">COLLECTION PERSONNELLE</p><h1><?= e($collection['name']) ?></h1><p class="subheading"><?= e($collection['description']) ?></p></div><div class="heading-actions"><a class="button secondary back-button" href="<?= e(url('collections')) ?>">&larr; Retour aux collections</a><form method="post" action="<?= e(url('collection-delete')) ?>" data-confirm="Supprimer cette collection ? Les vêtements de votre garde-robe seront conservés."><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($collection['id']) ?>"><button class="button danger">Supprimer la collection</button></form></div></section>
<div class="form-panel"><h2>Modifier la collection</h2><form method="post" action="<?= e(url('collection-save')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($collection['id']) ?>"><div class="form-row"><label>Nom<input name="name" maxlength="120" required value="<?= e($collection['name']) ?>"></label><label>Description<input name="description" value="<?= e($collection['description']) ?>"></label></div><div class="multi-select"><b>Pièces incluses (cochez pour ajouter, décochez pour retirer)</b><?php $selected=array_map('intval',array_column($items,'id'));foreach($clothes as $item): ?><label><input type="checkbox" name="items[]" value="<?= e($item['id']) ?>" <?= in_array((int)$item['id'],$selected,true)?'checked':'' ?>> <?= e($item['name']) ?></label><?php endforeach; ?></div><button class="button primary">Enregistrer</button></form></div>
<?php if($items): ?><div class="clothes-grid"><?php foreach($items as $item): ?><a class="clothing-card" href="<?= e(url('clothes-show',['id'=>$item['id']])) ?>"><div class="clothing-photo"><?php if($item['image_path']): ?><img src="<?= e(APP_BASE_URL.'/'.$item['image_path']) ?>" alt=""><?php else: ?><span>GRINGO</span><?php endif; ?></div><div class="clothing-meta"><span><?= e($item['label_name']) ?></span><h3><?= e($item['name']) ?></h3></div></a><?php endforeach; ?></div><?php else: ?><div class="empty-state"><h3>Cette collection ne contient pas encore de pièce</h3><p>Ajoutez des vêtements à l’aide du formulaire ci-dessus.</p></div><?php endif; ?>
